insert into public.official_exam_questions (question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,exam_year,career_name,exam_board,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note)
select qs.id,gs.id,t.id,$q$Polícia Civil de Minas Gerais – Delegado de Polícia Substituto$q$,2025,$q$Delegado de Polícia Substituto$q$,$q$FGV$q$,v.n,v.subj,v.txt,v.txt,v.ans,v.pg,v.st,v.legal,v.ctx,v.note
from (values (25,$q$Direito Constitucional$q$,$q$Após reunião de cúpula entre autoridades do Poder Executivo do Estado Alfa, decidiu-se pela necessidade de ser adotada política pública direcionada a um grupo específico, com histórico de exclusão social. Na ocasião, o assessor de um dos presentes sustentou que a referida política pública I. deveria ser instituída de modo contínuo; II. não poderia importar em discriminação reversa; III. poderia se distanciar da igualdade formal. A esse respeito, está correto o que se afirma em
(A) I, II e III.
(B) I, apenas.
(C) III, apenas.
(D) I e II, apenas.
(E) II e III, apenas.$q$,$q$C$q$,8,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(26,$q$Direito Civil$q$,$q$Leia o seguinte trecho do voto do Ministro Luis Felipe Salomão nº 1.415.727 – SC, julgado pela Quarta Turma do Superior Tribunal de Justiça. (...) E mais, o direito de receber doação (art. 542 do Código Civil), de ser curatelado (art. 1.779 do Código Civil), a especial proteção conferida à gestante, assegurando-se-lhe atendimento pré-natal (art. 8º do ECA, o qual, ao fim e ao cabo, visa a garantir o direito à vida e à saúde do nascituro), e recentemente a edição da Lei nº 11.804/2008, que positivou os chamados alimentos gravídicos, cuja titularidade é, na verdade, do nascituro e não da mãe. Porém, a par dos citados exemplos, parece ser no direito penal que a condição de pessoa viva do nascituro – embora não nascida – é afirmada sem a menor cerimônia. É que o crime de aborto (arts. 124 a 127 do CP) sempre esteve alocado no título referente a “crimes contra a pessoa” e especificamente no capítulo “dos crimes contra a vida” (...). A linha argumentativa adotada defende a teoria
(A) concepcionista.
(B) natalista.
(C) da personalidade condicionada.
(D) dos sujeitos de direito sem personalidade.
(E) natalista mitigada.$q$,$q$A$q$,9,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(27,$q$Direito Civil$q$,$q$João passeava com seu filho Pedrinho em um shopping, quando a criança, desavisadamente, sentou-se para descansar em uma mesa reservada à família de Gerônimo que ali jantaria. Quando Gerônimo viu a cena, fez um escândalo, inclusive xingando João de omisso e de péssimo pai. A cena foi gravada por um terceiro que a divulgou na internet. O vídeo se tornou viral, mas a maioria dos que o acessavam davam razão a João que, por isso mesmo, passou a participar de programas de televisão e a ser chamado para alguns trabalhos publicitários. Mesmo assim, João acionou Gerônimo requerendo indenização por danos morais. Nesse caso, os pedidos devem ser julgados
(A) procedentes, diante da violação aos direitos da personalidade.
(B) improcedentes, diante da ausência de danos efetivos, considerando que a exposição acabou sendo benéfica, inclusive financeiramente.
(C) improcedentes, por ausência de ato ilícito no exercício regular da liberdade de expressão.
(D) improcedentes, por ausência de nexo causal imputável ao réu, uma vez que a divulgação do vídeo foi obra de terceiro.
(E) improcedentes, porque o réu agiu em legítima defesa.$q$,$q$A$q$,9,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(28,$q$Direito Civil$q$,$q$Em um grande condomínio de Belo Horizonte/MG, existe apenas a marcação de uma vaga “prioridades” entre as mais de 100 existentes no estacionamento. Em um dia de grande movimento, dois carros chegaram mais ou menos ao mesmo tempo àquela vaga e se instaurou forte discussão sobre quem teria a preferência. Isto porque, em um dos carros, havia Pablo, pessoa com deficiência que contava 62 anos; no outro, João Marcos, aos 82 anos. Nesse caso, à luz exclusivamente do Estatuto do Idoso, avalie as afirmativas a seguir. I. Pablo ainda não atingiu a idade mínima para fazer jus às vagas de idoso (65 anos). II. A preferência, a que ambos fazem jus, será determinada por ordem de chegada, já que ambos são idosos. III. Embora ambos façam jus à reserva, João Marcos terá prioridade sobre Pablo, ainda que tenha chegado depois. Está correto o que se afirma em
(A) I, apenas.
(B) II, apenas.
(C) III, apenas.
(D) I e III, apenas.
(E) II e III, apenas.$q$,$q$C$q$,9,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(29,$q$Direito Civil$q$,$q$Um crime que tenha por objeto coisa alheia móvel, remetendo à definição do Código Civil, não poderá incidir sobre
(A) a viga de aço extraída de ponte que fora implodida.
(B) o veículo integrante de herança ainda não partilhada.
(C) o direito de crédito garantido por garantia imobiliária.
(D) a árvore de elevado valor econômico plantada no quintal.
(E) o material destinado à construção de um edifício, durante o transporte e depois da afetação à finalidade.$q$,$q$D$q$,9,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(30,$q$Direito Civil$q$,$q$Confira o trecho do voto do Ministro Gilson Dipp, no REsp nº 564.960/SC julgado pela Quinta Turma do Superior Tribunal de Justiça, ao tratar da responsabilidade penal das pessoas jurídicas. A responsabilização penal da pessoa jurídica pela prática de delitos ambientais surge, assim, como forma não apenas de punição das condutas lesivas ao meio ambiente, mas como forma mesmo de prevenção da prática de tais crimes, função essencial da política ambiental, que clama por preservação. (...) A responsabilização penal da pessoa jurídica, sendo decorrente de uma opção eminentemente política, conforme referido, depende, logicamente, de uma modificação da dogmática penal clássica para sua implementação e aplicação. A imputação penal às pessoas jurídicas encontra barreiras, assim, na suposta incapacidade de praticarem uma ação de relevância penal, de serem culpáveis e de sofrerem penalidades. Assinale a opção que indica a abordagem que remete à teoria explicativa da pessoa jurídica.
(A) Negativista, adotada pelo Código Civil.
(B) Equiparação, adotada pelo Código Civil.
(C) Ficção jurídica, não adotada pelo Código Civil.
(D) Realidade objetiva, adotada pelo Código Civil.
(E) Realidade técnica, não adotada pelo Código Civil.$q$,$q$C$q$,9,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(31,$q$Direito Penal e Legislação Penal Extravagante$q$,$q$João, primário, com bons antecedentes, no dia do seu aniversário de 20 anos de idade, foi capturado em flagrante após tentar subtrair, sem êxito, o telefone celular de Maria, mediante grave ameaça, com o emprego de um revólver, calibre .38, arma de fogo de uso permitido. Nesse cenário, considerando as disposições do Código Penal e o entendimento dominante dos Tribunais Superiores, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) João, além da pena privativa de liberdade, estará sujeito à pena de multa, que consiste no pagamento ao fundo penitenciário da quantia fixada na sentença e calculada em dias-multa, sendo, no mínimo, de 10 e, no máximo, de 360 dias-multa. ( ) João, ainda que as sanções aplicadas sejam inferiores a oito anos de reclusão, será submetido, inicialmente, ao regime fechado de cumprimento de pena, em razão da gravidade em abstrato do crime, que envolveu o emprego de arma de fogo. ( ) João, à época do crime, tinha menos de 21 anos de idade, o que ensejará a redução da pena na terceira fase do processo dosimétrico. As afirmativas são, respectivamente,
(A) V – F – V.
(B) F – V – F.
(C) V – F – F.
(D) V – V – V.
(E) F – F – V.$q$,$q$C$q$,10,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(32,$q$Direito Penal e Legislação Penal Extravagante$q$,$q$Durante um pacífico protesto realizado no interior do Município Alfa, Caio, destoando do público presente e agindo com dolo, lançou uma pedra em direção ao pequeno estabelecimento comercial de João, gerando, em razão dos bens móveis destruídos, prejuízo considerável para a vítima. Na sequência, Caio jogou diversos paralelepípedos contra a sede da municipalidade, deteriorando o bem público. Nesse cenário, considerando as disposições do Código Penal, é correto afirmar que Caio responderá, em concurso, pelos crimes de
(A) dano qualificado em detrimento de João e dano qualificado por ter deteriorado bem público, hipóteses em que se procede mediante ação penal pública incondicionada.
(B) dano qualificado em detrimento de João, hipótese em que somente se procede mediante representação do ofendido, e dano qualificado por ter deteriorado bem público.
(C) dano simples em detrimento de João e dano simples por ter deteriorado bem público, hipóteses em que se procede mediante ação penal pública incondicionada.
(D) dano qualificado em detrimento de João, hipótese em que somente se procede mediante queixa, e dano qualificado por ter deteriorado bem público.
(E) dano simples em detrimento de João, hipótese em que somente se procede mediante queixa, e dano qualificado por ter deteriorado bem público.$q$,$q$D$q$,10,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$)) v(n,subj,txt,ans,pg,st,legal,ctx,note)
